import React from 'react';
import './HotlineContacts.css';

const HotlineContacts = () => {
  const hotlines = [
    { name: 'Emergency Services', number: '911', description: 'Police, Fire, Medical' },
    { name: 'National Suicide Prevention', number: '988', description: '24/7 Crisis Support' },
    { name: 'Domestic Violence Hotline', number: '1-800-799-7233', description: 'Safe & Confidential' },
    { name: 'Crisis Text Line', number: 'Text HOME to 741741', description: 'Text-based Crisis Support' },
    { name: 'Poison Control', number: '1-800-222-1222', description: 'Poison Emergency' },
    { name: 'RAINN Sexual Assault', number: '1-800-656-4673', description: 'Sexual Assault Support' },
  ];

  const callNumber = (number) => {
    window.location.href = `tel:${number}`;
  };

  return (
    <div className="hotlines-container">
      <h2>Emergency Hotlines</h2>
      <div className="hotlines-list">
        {hotlines.map((hotline, index) => (
          <div key={index} className="hotline-item">
            <div className="hotline-info">
              <h3>{hotline.name}</h3>
              <p className="hotline-number">{hotline.number}</p>
              <p className="hotline-desc">{hotline.description}</p>
            </div>
            <button 
              onClick={() => callNumber(hotline.number)}
              className="call-btn"
            >
              📞 Call
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default HotlineContacts;
